47	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
48	import org.springframework.samples.petclinic.util.LocalityResolver;
49	import org.springframework.samples.petclinic.util.PostcodeValidator;
50	import org.springframework.samples.petclinic.util.Sha256Hex;
51	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /** Maximum number of owners a single city may contain; creating an owner in a city that
70	     *  already has this many owners is rejected with 409 Conflict. */
71	    private static final int MAX_OWNERS_PER_CITY = 50;
72	
73	    /** Maximum number of owners that may be created on a single day (by registration date); creating
74	     *  an owner once this many owners already carry today's registration date is rejected with
75	     *  429 Too Many Requests. */
76	    private static final int MAX_OWNERS_PER_DAY = 100;
77	
78	    /** When more than this many owners already carry today's registration date at creation time, the
79	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
80	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
81	
82	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    private final TelephoneNormalizer telephoneNormalizer;
94	
95	    private final HouseholdNormalizer householdNormalizer;
96	
97	    private final AddressNormalizer addressNormalizer;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper,
103	                                 TelephoneNormalizer telephoneNormalizer,
104	                                 HouseholdNormalizer householdNormalizer,
105	                                 AddressNormalizer addressNormalizer) {
106	        this.clinicService = clinicService;
107	        this.ownerMapper = ownerMapper;
108	        this.petMapper = petMapper;
109	        this.visitMapper = visitMapper;
110	        this.telephoneNormalizer = telephoneNormalizer;
111	        this.householdNormalizer = householdNormalizer;
112	        this.addressNormalizer = addressNormalizer;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        HttpHeaders headers = new HttpHeaders();
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        normalizeOwnerFields(owner);
146	        // Enforce the pre-persistence policies that can reject the new owner outright.
147	        rejectDisallowedOwnerCreation(owner);
148	        // Resolve the owner's household membership: assign the shared 'householdId' when the
149	        // request opts in and joins an existing household, and record the household size. This runs
150	        // before the identity-key check so that check sees the owner's final household id.
151	        applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
152	        // Reject the create when the owner's whole derived identity key (normalized telephone,
153	        // email and household id) already matches an existing owner. This single rule subsumes the
154	        // former separate telephone, email and household duplicate checks.
155	        rejectWhenIdentityInUse(owner);
156	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
157	        // shares an existing owner's last name and postcode with a different telephone.
158	        assignPossibleDuplicate(owner);
159	        // Assign the remaining create-time derived fields (namesake count, customer code,
160	        // membership number and bulk-signup warning), each fixed at creation time.
161	        assignDerivedFields(owner);
162	        this.clinicService.saveOwner(owner);
163	        // Emit an audit line for the successful create, carrying the owner id, customer code and
164	        // registration date so the create can be traced from the dedicated AUDIT log.
165	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
166	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
167	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
168	        headers.setLocation(UriComponentsBuilder.newInstance()
169	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
170	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
171	    }
172	
173	    /**
174	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
175	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
176	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
177	     * the sequence of create-time rejections stays readable and a new rule is added as one more
178	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
179	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
180	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
181	     * the household id has been resolved, because that key includes the household id.
182	     *
183	     * @param owner the newly mapped and normalized owner being created
184	     */
185	    private void rejectDisallowedOwnerCreation(Owner owner) {
186	        rejectWhenDailyLimitReached(owner);
187	        rejectWhenCityAtCapacity(owner);
188	    }
189	
190	    /**
191	     * Applies the household-membership rules for a newly normalized owner being created. It finds
192	     * the existing owners who share the owner's household (same last name and address, compared
193	     * case-insensitively with collapsed whitespace), then, using that single lookup: when the
194	     * request opts in via {@code sharesHousehold} and the owner joins an existing household, assigns
195	     * the new owner and every existing member the same stable {@code householdId}; and records the
196	     * owner's {@code householdSize}. Sharing a household is no longer a rejection on its own: a new
197	     * owner is rejected only when its whole identity key matches an existing owner (see
198	     * {@link #rejectWhenIdentityInUse}), and the household id resolved here is part of that key.
199	     *
200	     * @param owner           the newly mapped and normalized owner being created
201	     * @param sharesHousehold whether the request opted in to joining an existing household
202	     */
203	    private void applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
204	        // Identify any existing owners who share a household (same last name and address,
205	        // compared case-insensitively with collapsed whitespace) with the owner being created.
206	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
207	        // When opting in and joining an existing household, assign the new owner and every
208	        // existing member the same stable household identifier derived from the last name and
209	        // address, so all owners of the household share one 'householdId'.
210	        if (sharesHousehold && !householdMembers.isEmpty()) {
211	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
212	            owner.setHouseholdId(householdId);
213	            for (Owner member : householdMembers) {
214	                if (!householdId.equals(member.getHouseholdId())) {
215	                    member.setHouseholdId(householdId);
216	                    this.clinicService.saveOwner(member);
217	                }
218	            }
219	        }
220	        // Record the size of this owner's household after this create, i.e. the number of owners
221	        // sharing this owner's 'householdId' once it is persisted. An owner that shares an existing
222	        // household counts the matched members plus itself; an owner without a shared household is a
223	        // household of one. Fixed at creation time.
224	        owner.setHouseholdSize(owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1);
225	    }
226	
227	    /**
228	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
229	     * has already been resolved: the namesake count, the per-city customer code, the membership
230	     * number derived from that customer code and the registration year, and the bulk-signup warning
231	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
232	     * here keeps {@link #addOwner} focused on the high-level create sequence.
233	     *
234	     * @param owner the owner being created, already normalized and with its household resolved
235	     */
236	    private void assignDerivedFields(Owner owner) {
237	        // Record how many existing owners already share this owner's first and last name
238	        // (compared case-insensitively) before this create, fixed at creation time.
239	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
240	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
241	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
242	        // time.
243	        owner.setCustomerCode(customerCode(owner));
244	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
245	        // of the registration date's year (e.g. 'NSW-A1B2C3D4-M26'), fixed at creation time.
246	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
247	        // Flag the create when more than 80 owners have already been created on this owner's
248	        // (adjusted business-day) registration date, fixed at creation time.
249	        owner.setBulkSignupWarning(
250	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
251	    }
252	
253	    /**
254	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
255	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
256	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
257	     * the former separate telephone, email and household duplicate checks: two owners collide only
258	     * when their whole keys are equal, and members of one household with different telephones have
259	     * different keys and are both allowed.
260	     *
261	     * @param owner the owner being created, already normalized and with its household resolved
262	     */
263	    private void rejectWhenIdentityInUse(Owner owner) {
264	        String identityKey = owner.getIdentityKey();
265	        boolean inUse = existingOwners()
266	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
267	        if (inUse) {
268	            throw new DuplicateIdentityException(
269	                "An owner with identity key " + identityKey + " already exists");
270	        }
271	    }
272	
273	    /**
274	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
275	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
276	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
277	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
278	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
279	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
280	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
281	     * possible duplicate. Both values are fixed at creation time.
282	     *
283	     * @param owner the owner being created, already normalized and confirmed not a hard duplicate
284	     */
285	    private void assignPossibleDuplicate(Owner owner) {
286	        Integer matchId = owner.getPostcode() == null ? null : existingOwners()
287	            .filter(existing -> existing.getPostcode() != null
288	                && existing.getPostcode().equals(owner.getPostcode())
289	                && existing.getLastName() != null
290	                && existing.getLastName().equalsIgnoreCase(owner.getLastName())
291	                && existing.getTelephone() != null
292	                && !existing.getTelephone().equals(owner.getTelephone()))
293	            .map(Owner::getId)
294	            .min(Integer::compareTo)
295	            .orElse(null);
296	        owner.setPossibleDuplicate(matchId != null);
297	        owner.setPossibleDuplicateOf(matchId);
298	    }
299	
300	    /**
301	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
302	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
303	     *
304	     * @param owner the owner being created
305	     */
306	    private void rejectWhenDailyLimitReached(Owner owner) {
307	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
308	            throw new DailyOwnerLimitExceededException(
309	                "The maximum number of owners that may be created today has already been reached");
310	        }
311	    }
312	
313	    /**
314	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
315	     * or more owners, with 409 Conflict.
316	     *
317	     * @param owner the owner being created
318	     */
319	    private void rejectWhenCityAtCapacity(Owner owner) {
320	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
321	            throw new CityCapacityExceededException(
322	                "The city " + owner.getCity() + " already contains the maximum number of owners");
323	        }
324	    }
325	
326	    /**
327	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
328	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
329	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
330	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
331	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
332	     * server's current date. Canonicalising the address here, before the household checks read it,
333	     * ensures duplicate detection and the shared household id both compare the normalized form.
334	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
335	     * duplicate, household and customer-code rules.
336	     *
337	     * @param owner the newly mapped owner to canonicalize
338	     */
339	    private void normalizeOwnerFields(Owner owner) {
340	        // Normalize the address on create so it is stored and returned in canonical form and every
341	        // later comparison (household duplicate detection and the shared household id) uses it.
342	        // A value that is blank after normalization is rejected with 400.
343	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
344	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
345	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
346	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
347	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
348	        // Store the (already syntactically validated) email lower-cased so it is persisted and
349	        // returned in canonical form. A missing email is left untouched.
350	        owner.setEmail(normalizeEmail(owner.getEmail()));
351	        // Validate the optional postcode against the fixed range for the city's region. A postcode
352	        // is checked only when present (it is optional); one out of range for the city's region is
353	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
354	        // value is left unchanged.
355	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
356	        // Reject a supplied registration date that is later than the server's current date with
357	        // 400, before any defaulting or business-day adjustment, so a future date is never
358	        // persisted regardless of how the roll-forward would move it.
359	        rejectFutureRegistrationDate(owner.getRegistrationDate());
360	        // Default the registration date to the server's current date when the client did not
361	        // supply one, then roll the effective date forward to a business day so a Saturday or
362	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
363	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
364	        // date-derived field (such as the membership number's year segment) and the per-day
365	        // create-limit are computed from.
366	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
367	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
368	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
369	    }
370	
371	    /**
372	     * Rejects a supplied registration date that is later than the server's current date with a
373	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
374	     * accepted, and a date on or before today is left for the normal defaulting and business-day
375	     * adjustment.
376	     *
377	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
378	     */
379	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
380	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
381	            throw new InvalidRegistrationDateException(
382	                "The supplied registration date " + registrationDate + " is later than the current date");
383	        }
384	    }
385	
386	    /**
387	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
388	     * following Monday, while a weekday is returned unchanged. Applied to the effective
389	     * registration date (whether supplied in the request or defaulted to the server date) so the
390	     * persisted registration date, every value derived from it and the per-day create-limit all
391	     * use the adjusted business day.
392	     *
393	     * @param date the effective registration date
394	     * @return the same date if it is a weekday, otherwise the following Monday
395	     */
396	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
397	        java.time.LocalDate adjusted = date;
398	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
399	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
400	            adjusted = adjusted.plusDays(1);
401	        }
402	        return adjusted;
403	    }
404	
405	    /**
406	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
407	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
408	     * syntactically valid address (rejecting anything else with 400).
409	     *
410	     * @param email the email value (may be {@code null})
411	     * @return the lower-cased email, or {@code null} if the input was {@code null}
412	     */
413	    private String normalizeEmail(String email) {
414	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
415	    }
416	
417	    /**
418	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
419	     * region derived from the owner's postcode (falling back to the city, via
420	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
421	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
422	     * 'NSW-A1B2C3D4'). The identity carries no sequence number, so it is a pure function of the
423	     * owner's region and identity fields.
424	     *
425	     * @param owner the owner being created, already normalized
426	     * @return the formatted customer code
427	     */
428	    private String customerCode(Owner owner) {
429	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
430	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
431	        return region + "-" + hash8;
432	    }
433	
434	    /**
435	     * Streams the existing owners that the create-time rules match a new owner against. Every
436	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
437	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
438	     * own matching criterion rather than on how the existing owners are retrieved.
439	     *
440	     * @return a stream over all existing owners
441	     */
442	    private Stream<Owner> existingOwners() {
443	        return this.clinicService.findAllOwners().stream();
444	    }
445	
446	    /**
447	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
448	     * fix the per-city sequence of an owner's customer code at creation time.
449	     *
450	     * @param city the city of the owner being created
451	     * @return the number of existing owners in a matching city
452	     */
453	    private int countOwnersInCity(String city) {
454	        return (int) existingOwners()
455	            .filter(existing -> existing.getCity() != null
456	                && existing.getCity().equalsIgnoreCase(city))
457	            .count();
458	    }
459	
460	    /**
461	     * Counts the existing owners whose registration date is the given adjusted business day. Used
462	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
463	     * owners already carry that business day as their registration date.
464	     *
465	     * @param date the adjusted business-day registration date to match
466	     * @return the number of existing owners registered on that date
467	     */
468	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
469	        return (int) existingOwners()
470	            .filter(existing -> date.equals(existing.getRegistrationDate()))
471	            .count();
472	    }
473	
474	    /**
475	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
476	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
477	     *
478	     * @param customerCode     the owner's customer code
479	     * @param registrationDate the owner's registration date
480	     * @return the formatted membership number
481	     */
482	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
483	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
484	    }
485	
486	    /**
487	     * Returns the existing owners who share the given household, i.e. have the same last name and
488	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
489	     * differing only in letter case or in incidental whitespace are treated as the same household.
490	     *
491	     * @param lastName the last name of the owner being created
492	     * @param address  the address of the owner being created
493	     * @return the existing owners with a matching last name and address (possibly empty)
494	     */
495	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
496	        String householdKey = householdNormalizer.householdKey(lastName, address);
497	        return existingOwners()
498	            .filter(existing -> householdNormalizer
499	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
500	            .toList();
501	    }
502	
503	    /**
504	     * Counts the existing owners who share the given first and last name, compared
505	     * case-insensitively. Used to fix an owner's namesake count at creation time.
506	     *
507	     * @param firstName the first name of the owner being created
508	     * @param lastName  the last name of the owner being created
509	     * @return the number of existing owners with a matching first and last name
510	     */
511	    private int countNamesakes(String firstName, String lastName) {
512	        return (int) existingOwners()
513	            .filter(existing -> existing.getFirstName() != null
514	                && existing.getFirstName().equalsIgnoreCase(firstName)
515	                && existing.getLastName() != null
516	                && existing.getLastName().equalsIgnoreCase(lastName))
517	            .count();
518	    }
519	
520	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
521	    @Override
522	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
523	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
524	        if (currentOwner == null) {
525	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
526	        }
527	        currentOwner.setAddress(ownerFieldsDto.getAddress());
528	        currentOwner.setCity(ownerFieldsDto.getCity());
529	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
530	        currentOwner.setLastName(ownerFieldsDto.getLastName());
531	        // Normalize the telephone to canonical E.164 form so it is stored and returned
532	        // consistently with create; an unformattable value is rejected with 400.
533	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
534	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
535	        this.clinicService.saveOwner(currentOwner);
536	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
537	    }
538	
539	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
540	    @Transactional
541	    @Override
542	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
543	        Owner owner = this.clinicService.findOwnerById(ownerId);
544	        if (owner == null) {
545	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
546	        }
547	        this.clinicService.deleteOwner(owner);
548	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
549	    }
550	
551	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
552	    @Override
553	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
554	        Owner owner = this.clinicService.findOwnerById(ownerId);
555	        if (owner == null) {
556	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
557	        }
558	        HttpHeaders headers = new HttpHeaders();
559	        Pet pet = petMapper.toPet(petFieldsDto);
560	        owner.setId(ownerId);
561	        pet.setOwner(owner);
562	        pet.getType().setName(null);
563	        this.clinicService.savePet(pet);
564	        PetDto petDto = petMapper.toPetDto(pet);
565	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
566	            .buildAndExpand(pet.getId()).toUri());
567	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
568	    }
569	
570	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
571	    @Override
572	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
573	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
574	        if (currentOwner != null) {
575	            Pet currentPet = this.clinicService.findPetById(petId);
576	            if (currentPet != null) {
577	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
578	                currentPet.setName(petFieldsDto.getName());
579	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
580	                this.clinicService.savePet(currentPet);
581	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
582	            }
583	        }
584	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
585	    }
586	
587	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
588	    @Override
589	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
590	        HttpHeaders headers = new HttpHeaders();
591	        Visit visit = visitMapper.toVisit(visitFieldsDto);
592	        Pet pet = new Pet();
593	        pet.setId(petId);
594	        visit.setPet(pet);
595	        this.clinicService.saveVisit(visit);
596	        VisitDto visitDto = visitMapper.toVisitDto(visit);
597	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
598	            .buildAndExpand(visit.getId()).toUri());
599	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
600	    }
601	
602	
603	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
604	    @Override
605	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
606	        Owner owner = this.clinicService.findOwnerById(ownerId);
607	        if (owner != null) {
608	            Pet pet = owner.getPet(petId);
609	            if (pet != null) {
610	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
611	            }
612	        }
613	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
614	    }
615	}
